"""The course report's folder, ``report/``: the generated files ``report.tex`` inputs, and its tables as Markdown.

``python -m ecgaug.paper`` writes every generated file under ``paper/generated/`` (the paper itself is kept out of the
repository) and then calls :func:`write`. It copies only the files ``report/report.tex`` inputs into
``report/generated/``, so the folder holds the report and its results and none of the paper's own texts. It also writes
``report/results.md``: every results table of the report, in the order of its sections, as Markdown that GitHub shows.
The Markdown is converted from the same generated tables; nothing in it is typed by hand (docs/RULES.md rule 5).
"""

from __future__ import annotations

import re
import shutil
from pathlib import Path

from ecgaug import paths

FOLDER = "report"
NOT_RESULTS = {"numbers.tex", "report_architecture.tex", "report_example.tex"}  # number macros, layer tables, one example output
_INPUT = re.compile(r"\\input\{generated/([^}]*)\}")
_RULES = re.compile(r"\\(?:toprule|midrule|bottomrule|hline|addlinespace)\b(?:\[[^\]]*\])?|\\cmidrule(?:\([^)]*\))?\{[^}]*\}")
_SOURCES = re.compile(r"^% Generated by python -m ecgaug\.paper from: (.*)$", re.M)
_ALIGN = {"l": ":---", "r": "---:", "c": ":---:"}
_PLAIN = [("$-$", "\u2212"), ("^\\dagger", "\u2020"), ("\\dagger", "\u2020"), ("\\pm", "\u00b1"), ("\\times", "\u00d7"),
          ("\\%", "%"), ("\\&", "&"), ("\\_", "_"), ("\\#", "#"), ("---", "\u2014"), ("--", "\u2013"), ("\\,", " "), ("~", " "),
          ("\\ ", " ")]  # fmt: skip
_CELL_PATTERNS = [
    (re.compile(r"\\missing\{([^{}]*)\}"), r"[\1]"),
    (re.compile(r"\\textbf\{([^{}]*)\}"), r"**\1**"),
    (re.compile(r"\\(?:textit|emph)\{([^{}]*)\}"), r"*\1*"),
    (re.compile(r"\\texttt\{([^{}]*)\}"), r"`\1`"),
    (re.compile(r"\s*\\cite[pt]?\{([^{}]*)\}"), lambda m: " [" + ", ".join(k.strip() for k in m.group(1).split(",")) + "]"),
    (re.compile(r"\\(?:label|ref)\{[^{}]*\}"), ""),
    (re.compile(r"\\multicolumn\{\d+\}\{[^{}]*\}\{([^{}]*)\}"), r"\1"),
    (re.compile(r"\\[a-zA-Z]+\*?(?:\[[^\]]*\])?\{([^{}]*)\}"), r"\1"),
]


def folder() -> Path:
    """The report folder of the current root."""
    return paths.repo_root() / FOLDER


def inputs(tex: str) -> list[str]:
    """The generated files a LaTeX text inputs, in order of first use."""
    return list(dict.fromkeys(n if n.endswith(".tex") else f"{n}.tex" for n in _INPUT.findall(tex)))


def write(generated: Path) -> list[str]:
    """Copy the files ``report/report.tex`` inputs from ``generated`` into ``report/generated/``; write ``report/results.md``.

    Files that the generated files input in turn are copied too (numbers.tex inputs the final evaluation's numbers), and
    files of ``report/generated/`` the report no longer inputs are removed. Returns the files written, relative to the
    root; without ``report/report.tex`` nothing is written.
    """
    source = folder() / "report.tex"
    if not source.is_file():
        return []
    tex = source.read_text()
    names = inputs(tex)
    for name in names:  # the list grows while it is walked, so nested inputs are followed to any depth
        names += [n for n in inputs((generated / name).read_text()) if n not in names]
    target = folder() / "generated"
    target.mkdir(exist_ok=True)
    for stale in target.glob("*.tex"):
        if stale.name not in names:
            stale.unlink()
    for name in names:
        shutil.copy2(generated / name, target / name)
    (folder() / "results.md").write_text(results_markdown(tex, target))
    return [f"{FOLDER}/generated/{n}" for n in names] + [f"{FOLDER}/results.md"]


def _braced(text: str, start: int) -> tuple[str, int]:
    """The text inside the brace group that opens at ``start``, and the index just after the group."""
    depth = 0
    for i in range(start, len(text)):
        if text[i] in "{}" and (i == 0 or text[i - 1] != "\\"):
            depth += 1 if text[i] == "{" else -1
            if depth == 0:
                return text[start + 1 : i], i + 1
    raise ValueError(f"unbalanced braces after position {start}")


def _caption_around(text: str, pos: int) -> str | None:
    """The caption of the table environment that holds position ``pos``, if there is one."""
    start = text.rfind("\\begin{table}", 0, pos)
    if start < 0 or text.rfind("\\end{table}", 0, pos) > start:
        return None
    end = text.find("\\end{table}", pos)
    at = text.find("\\caption{", start, end if end >= 0 else len(text))
    return _braced(text, at + len("\\caption"))[0] if at >= 0 else None


def cell(text: str) -> str:
    """One LaTeX table cell or caption as Markdown text."""
    for old, new in _PLAIN:
        text = text.replace(old, new)
    while True:  # innermost groups first, until nothing changes
        before = text
        for pattern, replacement in _CELL_PATTERNS:
            text = pattern.sub(replacement, text)
        if text == before:
            break
    text = re.sub(r"\\[a-zA-Z]+\*?", "", text).replace("$", "").replace("{", "").replace("}", "").replace("( [", "([")
    return re.sub(r"\s+", " ", text).strip().replace("|", "\\|")


def split_caption(text: str) -> tuple[str, str]:
    """A caption's first sentence or clause (the title), and the rest; a stop inside brackets does not end the title."""
    depth = 0
    for i, ch in enumerate(text):
        depth += (ch in "([") - (ch in ")]")
        if ch in ".:" and depth == 0 and text[i + 1 : i + 2] in (" ", "") and text[i - 1 : i].isalpha() | (text[i - 1 : i] == ")"):
            rest = text[i + 1 :].strip()
            return text[:i], rest[:1].upper() + rest[1:]
    return text, ""


def markdown_table(spec: str, body: str) -> str:
    """A LaTeX tabular (its column spec and body) as a Markdown table; the first row is the header."""
    body = "\n".join(line for line in body.splitlines() if not line.lstrip().startswith("%"))
    rows = []
    for raw in re.split(r"\\\\(?:\[[^\]]*\])?", body):
        row = _RULES.sub("", raw).strip()
        if row:
            rows.append([cell(c) for c in re.split(r"(?<!\\)&", row)])
    width = max(len(r) for r in rows)
    rows = [r + [""] * (width - len(r)) for r in rows]
    letters = re.sub(r"[pmbX]\{[^{}]*\}", "p", re.sub(r"[@<>!]\{[^{}]*\}|\|", "", spec))
    align = [_ALIGN.get(ch, "---") for ch in letters] if len(letters) == width else ["---"] * width
    return "\n".join(["| " + " | ".join(rows[0]) + " |", "| " + " | ".join(align) + " |"] + ["| " + " | ".join(r) + " |" for r in rows[1:]])


def tables(text: str, caption: str | None = None) -> list[tuple[str | None, str, list[str]]]:
    """Each tabular of a generated file: (its caption, the Markdown table, the result files it lists as its sources).

    A tabular inside a table environment of the file takes that environment's caption, any other the given ``caption``.
    """
    out, last = [], 0
    for m in re.finditer(r"\\begin\{tabular\}", text):
        spec, start = _braced(text, m.end())
        end = text.index("\\end{tabular}", start)
        sources = _SOURCES.findall(text[last : m.start()])
        files = [s.strip() for s in sources[-1].split(",") if s.strip() and s.strip() != "nothing yet"] if sources else []
        out.append((_caption_around(text, m.start()) or caption, markdown_table(spec, text[start:end]), files))
        last = end
    return out


def results_markdown(tex: str, generated: Path) -> str:
    """Every results table the report inputs, under the report's section titles, as one Markdown page."""
    lines = ["# Results", "",
             "Every results table of the course report ([report.pdf](report.pdf)), in the order of its sections. Generated by",
             "`python -m ecgaug.paper` from the result files; do not edit by hand. A value in [brackets] is a result that does",
             "not exist yet, and bold marks what the report marks in bold. The report explains each table and shows the figures."]  # fmt: skip
    events = sorted([(m.start(), "", m.group(1)) for m in re.finditer(r"\\section\*?\{([^}]*)\}", tex)]
                    + [(m.start(), m.group(1), "") for m in _INPUT.finditer(tex)])  # fmt: skip
    section, shown = None, None
    for pos, name, title in events:
        if not name:
            section = cell(title)
            continue
        name = name if name.endswith(".tex") else f"{name}.tex"
        if name in NOT_RESULTS or not (generated / name).is_file():
            continue
        for caption, table, files in tables((generated / name).read_text(), _caption_around(tex, pos)):
            if section != shown:
                lines += ["", f"## {section}"]
                shown = section
            title, note = split_caption(cell(caption)) if caption else (name.removesuffix(".tex"), "")
            lines += ["", f"### {title}", "", table] + (["", note] if note else [])
            if files:
                lines += ["", "From " + ", ".join(f"`{f}`" for f in files) + "."]
    return "\n".join(lines) + "\n"
